export type EventHandler = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, Set<EventHandler>> = new Map();

  subscribe(eventName: string, handler: EventHandler): () => void {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, new Set());
    }
    const set = this.subscribers.get(eventName)!;
    set.add(handler);
    return () => {
      set.delete(handler);
    };
  }

  publish(eventName: string, payload: any): void {
    const handlers = this.subscribers.get(eventName);
    if (!handlers) return;
    // Call handlers in try/catch to avoid one failing handler breaking others
    for (const h of Array.from(handlers)) {
      try {
        h(payload);
      } catch (err) {
        // eslint-disable-next-line no-console
        console.error(`Error handling event ${eventName}:`, err);
      }
    }
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();

  create(name: string, email: string): User {
    const user: User = { id: randomUUID(), name, email };
    this.users.set(user.id, user);
    return user;
  }

  list(): User[] {
    return Array.from(this.users.values());
  }

  get(id: string): User | undefined {
    return this.users.get(id);
  }

  update(id: string, updates: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.users.get(id);
    if (!existing) return undefined;
    const updated: User = { ...existing, ...updates, id: existing.id };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  members: string[]; // user IDs
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  create(name: string, description: string): Project {
    const project: Project = { id: randomUUID(), name, description, members: [] };
    this.projects.set(project.id, project);
    return project;
  }

  list(): Project[] {
    return Array.from(this.projects.values());
  }

  get(id: string): Project | undefined {
    return this.projects.get(id);
  }

  update(id: string, updates: Partial<Omit<Project, 'id' | 'members'>>): Project | undefined {
    const existing = this.projects.get(id);
    if (!existing) return undefined;
    const updated: Project = { ...existing, ...updates, id: existing.id, members: existing.members };
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    if (!project.members.includes(userId)) {
      project.members.push(userId);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    project.members = project.members.filter(m => m !== userId);
    return project;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assignee?: string; // user ID
  projectId: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();

  constructor(private bus: EventBus) {}

  create(title: string, description: string, projectId: string, assignee?: string): Task {
    const task: Task = { id: randomUUID(), title, description, status: 'todo', projectId, assignee };
    this.tasks.set(task.id, task);
    this.bus.publish('task.created', { task });
    if (assignee) {
      this.bus.publish('task.assigned', { taskId: task.id, assignee, projectId });
    }
    return task;
  }

  list(filter?: { projectId?: string }): Task[] {
    let out = Array.from(this.tasks.values());
    if (filter?.projectId) {
      out = out.filter(t => t.projectId === filter.projectId);
    }
    return out;
  }

  get(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  update(id: string, updates: Partial<Omit<Task, 'id' | 'status'>>): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...updates, id: existing.id, status: existing.status };
    this.tasks.set(id, updated);
    this.bus.publish('task.updated', { task: updated });
    return updated;
  }

  delete(id: string): boolean {
    const task = this.tasks.get(id);
    const deleted = this.tasks.delete(id);
    if (deleted && task) {
      this.bus.publish('task.deleted', { task });
    }
    return deleted;
  }

  assign(id: string, assignee: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assignee = assignee;
    this.tasks.set(id, task);
    this.bus.publish('task.assigned', { taskId: id, assignee, projectId: task.projectId });
    return task;
  }

  setStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const currentIndex = order.indexOf(task.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) return undefined;
    if (newIndex < currentIndex || newIndex - currentIndex > 1) {
      // invalid transition
      return undefined;
    }
    task.status = newStatus;
    this.tasks.set(id, task);
    this.bus.publish('task.statusChanged', { taskId: id, status: newStatus, assignee: task.assignee, projectId: task.projectId });
    return task;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: number; // timestamp ms
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private bus: EventBus) {}

  create(taskId: string, authorId: string, body: string): Comment {
    const comment: Comment = { id: randomUUID(), taskId, authorId, body, createdAt: Date.now() };
    this.comments.set(comment.id, comment);
    this.bus.publish('comment.added', { comment });
    return comment;
  }

  list(filter?: { taskId?: string }): Comment[] {
    let out = Array.from(this.comments.values());
    if (filter?.taskId) {
      out = out.filter(c => c.taskId === filter.taskId);
    }
    return out.sort((a, b) => a.createdAt - b.createdAt);
  }

  get(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  delete(id: string): boolean {
    return this.comments.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private bus: EventBus) {
    // Subscriptions
    this.bus.subscribe('task.assigned', ({ taskId, assignee }: { taskId: string; assignee: string }) => {
      this.create(assignee, `You have been assigned to task ${taskId}`);
    });

    this.bus.subscribe('task.statusChanged', ({ taskId, status, assignee }: { taskId: string; status: string; assignee?: string }) => {
      if (assignee) {
        this.create(assignee, `Task ${taskId} status changed to ${status}`);
      }
    });

    this.bus.subscribe('comment.added', ({ comment }: { comment: { taskId: string; authorId: string; body: string } }) => {
      // We don't know task assignee here without calling TaskService. Instead, publish a secondary event
      // that someone else (like the API layer) could enrich. For simplicity in this in-memory system,
      // we also listen for an enriched event comment.added.enriched
      this.bus.publish('comment.added.needsAssignee', { taskId: comment.taskId, authorId: comment.authorId, body: comment.body });
    });

    this.bus.subscribe('comment.added.enriched', ({ taskId, assignee, authorId }: { taskId: string; assignee?: string; authorId: string }) => {
      if (assignee) {
        this.create(assignee, `New comment on task ${taskId} by user ${authorId}`);
      }
    });
  }

  private create(userId: string, message: string): Notification {
    const n: Notification = { id: randomUUID(), userId, message, read: false, timestamp: Date.now() };
    this.notifications.set(n.id, n);
    return n;
  }

  list(filter?: { userId?: string }): Notification[] {
    let out = Array.from(this.notifications.values());
    if (filter?.userId) {
      out = out.filter(n => n.userId === filter.userId);
    }
    return out.sort((a, b) => a.timestamp - b.timestamp);
  }

  get(id: string): Notification | undefined {
    return this.notifications.get(id);
  }

  markRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    this.notifications.set(id, n);
    return n;
  }
}

import { IncomingMessage, ServerResponse } from 'http';
import { parse as parseUrl } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export interface Services {
  users: UserService;
  projects: ProjectService;
  tasks: TaskService;
  comments: CommentService;
  notifications: NotificationService;
}

async function readJsonBody<T = any>(req: IncomingMessage): Promise<T | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk) => chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)));
    req.on('end', () => {
      if (chunks.length === 0) return resolve(undefined);
      const str = Buffer.concat(chunks).toString('utf8');
      if (!str) return resolve(undefined);
      try {
        const obj = JSON.parse(str);
        resolve(obj);
      } catch (err) {
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', (err) => reject(err));
  });
}

function sendJson(res: ServerResponse, status: number, data: any): void {
  const body = JSON.stringify(data);
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Length', Buffer.byteLength(body));
  res.end(body);
}

function notFound(res: ServerResponse): void {
  sendJson(res, 404, { error: 'Not Found' });
}

function badRequest(res: ServerResponse, msg = 'Bad Request'): void {
  sendJson(res, 400, { error: msg });
}

export function createApiRouter(services: Services) {
  return async function handler(req: IncomingMessage, res: ServerResponse) {
    const method = (req.method || 'GET').toUpperCase();
    const url = parseUrl(req.url || '', true);
    const path = url.pathname || '/';

    try {
      // Users
      if (path === '/users' && method === 'GET') {
        return sendJson(res, 200, services.users.list());
      }
      if (path === '/users' && method === 'POST') {
        const body = await readJsonBody(req);
        if (!body || typeof body.name !== 'string' || typeof body.email !== 'string') {
          return badRequest(res, 'name and email are required');
        }
        const user = services.users.create(body.name, body.email);
        return sendJson(res, 201, user);
      }
      const userIdMatch = path.match(/^\/users\/([^/]+)$/);
      if (userIdMatch) {
        const id = userIdMatch[1];
        if (method === 'GET') {
          const u = services.users.get(id);
          return u ? sendJson(res, 200, u) : notFound(res);
        }
        if (method === 'PUT') {
          const body = await readJsonBody(req);
          if (!body) return badRequest(res);
          const u = services.users.update(id, { name: body.name, email: body.email });
          return u ? sendJson(res, 200, u) : notFound(res);
        }
        if (method === 'DELETE') {
          const ok = services.users.delete(id);
          return ok ? sendJson(res, 204, {}) : notFound(res);
        }
      }

      // Projects
      if (path === '/projects' && method === 'GET') {
        return sendJson(res, 200, services.projects.list());
      }
      if (path === '/projects' && method === 'POST') {
        const body = await readJsonBody(req);
        if (!body || typeof body.name !== 'string' || typeof body.description !== 'string') {
          return badRequest(res, 'name and description are required');
        }
        const project = services.projects.create(body.name, body.description);
        return sendJson(res, 201, project);
      }
      const projectIdMatch = path.match(/^\/projects\/([^/]+)$/);
      if (projectIdMatch) {
        const id = projectIdMatch[1];
        if (method === 'GET') {
          const p = services.projects.get(id);
          return p ? sendJson(res, 200, p) : notFound(res);
        }
        if (method === 'PUT') {
          const body = await readJsonBody(req);
          if (!body) return badRequest(res);
          const p = services.projects.update(id, { name: body.name, description: body.description });
          return p ? sendJson(res, 200, p) : notFound(res);
        }
        if (method === 'DELETE') {
          const ok = services.projects.delete(id);
          return ok ? sendJson(res, 204, {}) : notFound(res);
        }
      }
      const projectMembersMatch = path.match(/^\/projects\/([^/]+)\/members$/);
      if (projectMembersMatch) {
        const id = projectMembersMatch[1];
        if (method === 'POST') {
          const body = await readJsonBody(req);
          if (!body || typeof body.userId !== 'string') return badRequest(res, 'userId required');
          const p = services.projects.addMember(id, body.userId);
          return p ? sendJson(res, 200, p) : notFound(res);
        }
        if (method === 'DELETE') {
          const body = await readJsonBody(req);
          if (!body || typeof body.userId !== 'string') return badRequest(res, 'userId required');
          const p = services.projects.removeMember(id, body.userId);
          return p ? sendJson(res, 200, p) : notFound(res);
        }
      }

      // Tasks
      if (path === '/tasks' && method === 'GET') {
        const projectId = typeof url.query.projectId === 'string' ? url.query.projectId : undefined;
        return sendJson(res, 200, services.tasks.list({ projectId }));
      }
      if (path === '/tasks' && method === 'POST') {
        const body = await readJsonBody(req);
        if (!body || typeof body.title !== 'string' || typeof body.description !== 'string' || typeof body.projectId !== 'string') {
          return badRequest(res, 'title, description, and projectId are required');
        }
        const task = services.tasks.create(body.title, body.description, body.projectId, body.assignee);
        return sendJson(res, 201, task);
      }
      const taskIdMatch = path.match(/^\/tasks\/([^/]+)$/);
      if (taskIdMatch) {
        const id = taskIdMatch[1];
        if (method === 'GET') {
          const t = services.tasks.get(id);
          return t ? sendJson(res, 200, t) : notFound(res);
        }
        if (method === 'PUT') {
          const body = await readJsonBody(req);
          if (!body) return badRequest(res);
          const t = services.tasks.update(id, { title: body.title, description: body.description, assignee: body.assignee });
          return t ? sendJson(res, 200, t) : notFound(res);
        }
        if (method === 'DELETE') {
          const ok = services.tasks.delete(id);
          return ok ? sendJson(res, 204, {}) : notFound(res);
        }
      }
      const taskStatusMatch = path.match(/^\/tasks\/([^/]+)\/status$/);
      if (taskStatusMatch && method === 'PUT') {
        const id = taskStatusMatch[1];
        const body = await readJsonBody(req);
        if (!body || typeof body.status !== 'string') return badRequest(res, 'status required');
        const t = services.tasks.setStatus(id, body.status);
        if (!t) return badRequest(res, 'invalid status transition or task not found');
        return sendJson(res, 200, t);
      }
      const taskAssignMatch = path.match(/^\/tasks\/([^/]+)\/assign$/);
      if (taskAssignMatch && method === 'PUT') {
        const id = taskAssignMatch[1];
        const body = await readJsonBody(req);
        if (!body || typeof body.assignee !== 'string') return badRequest(res, 'assignee required');
        const t = services.tasks.assign(id, body.assignee);
        return t ? sendJson(res, 200, t) : notFound(res);
      }

      // Comments
      if (path === '/comments' && method === 'GET') {
        const taskId = typeof url.query.taskId === 'string' ? url.query.taskId : undefined;
        return sendJson(res, 200, services.comments.list({ taskId }));
      }
      if (path === '/comments' && method === 'POST') {
        const body = await readJsonBody(req);
        if (!body || typeof body.taskId !== 'string' || typeof body.authorId !== 'string' || typeof body.body !== 'string') {
          return badRequest(res, 'taskId, authorId and body are required');
        }
        const c = services.comments.create(body.taskId, body.authorId, body.body);
        return sendJson(res, 201, c);
      }
      const commentIdMatch = path.match(/^\/comments\/([^/]+)$/);
      if (commentIdMatch) {
        const id = commentIdMatch[1];
        if (method === 'GET') {
          const c = services.comments.get(id);
          return c ? sendJson(res, 200, c) : notFound(res);
        }
        if (method === 'DELETE') {
          const ok = services.comments.delete(id);
          return ok ? sendJson(res, 204, {}) : notFound(res);
        }
      }

      // Notifications
      if (path === '/notifications' && method === 'GET') {
        const userId = typeof url.query.userId === 'string' ? url.query.userId : undefined;
        return sendJson(res, 200, services.notifications.list({ userId }));
      }
      const notifReadMatch = path.match(/^\/notifications\/([^/]+)\/read$/);
      if (notifReadMatch && method === 'PUT') {
        const id = notifReadMatch[1];
        const n = services.notifications.markRead(id);
        return n ? sendJson(res, 200, n) : notFound(res);
      }

      // Default
      notFound(res);
    } catch (err: any) {
      sendJson(res, 500, { error: err?.message || 'Internal Server Error' });
    }
  };
}

import http from 'http';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { createApiRouter } from './api-router';

// Wire services and event bus
const bus = new EventBus();
const users = new UserService();
const projects = new ProjectService();
const tasks = new TaskService(bus);
const comments = new CommentService(bus);
const notifications = new NotificationService(bus);

// Enrich comment.added.needsAssignee by looking up the task
bus.subscribe('comment.added.needsAssignee', ({ taskId, authorId }: { taskId: string; authorId: string }) => {
  const task = tasks.get(taskId);
  bus.publish('comment.added.enriched', { taskId, assignee: task?.assignee, authorId });
});

const router = createApiRouter({ users, projects, tasks, comments, notifications });

const server = http.createServer((req, res) => router(req, res));

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
server.listen(PORT, () => {
  // eslint-disable-next-line no-console
  console.log(`Task Management API listening on http://localhost:${PORT}`);
});

